{"path": "features/scheme_finder.py", "content": """"Scheme finder integration and eligibility explanations.

The production path fetches schemes from the configured government schemes API,
parses the user's short biography into a small applicant profile, and returns a
reasoned eligibility decision for each scheme.
"""

from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass
from typing import Any
from urllib.error import URLError
from urllib.request import Request, urlopen

DEFAULT_GOV_SCHEMES_API_URL = "https://www.gov.uk/api/schemes"


class BioValidationError(ValueError):
    """Raised when the supplied applicant bio cannot be evaluated safely."""


@dataclass(frozen=True)
class ApplicantProfile:
    bio: str
    income: int
    age: int | None = None
    location: str | None = None


@dataclass(frozen=True)
class EligibilityResult:
    id: str | None
    name: str
    eligible: bool
    explanation: str

    def as_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "name": self.name,
            "eligible": self.eligible,
            "explanation": self.explanation,
        }


def validate_and_parse_bio(bio: str) -> ApplicantProfile:
    """Validate a free-text bio and extract fields used for eligibility checks.

    We keep the parser intentionally conservative: an income is required because
    every supported scheme can be filtered by income, while age and location are
    optional and only used when present.  The function accepts natural phrases
    like "I am 67 and earn £12,000 in rural Devon".
    """

    if bio is None:
        raise BioValidationError("Bio is required.")
    if not isinstance(bio, str):
        raise BioValidationError("Bio must be text.")

    normalised = " ".join(bio.strip().split())
    if not normalised:
        raise BioValidationError("Bio is required.")
    if len(normalised) < 8:
        raise BioValidationError("Bio is too short to assess eligibility.")
    if len(normalised) > 1000:
        raise BioValidationError("Bio must be 1000 characters or fewer.")
    if any(ord(ch) < 32 for ch in normalised):
        raise BioValidationError("Bio contains unsupported control characters.")

    income = _extract_income(normalised)
    if income is None:
        raise BioValidationError("Please include your annual income in the bio.")
    if income < 0 or income > 10_000_000:
        raise BioValidationError("Income must be a realistic annual amount.")

    return ApplicantProfile(
        bio=normalised,
        income=income,
        age=_extract_age(normalised),
        location=_extract_location(normalised),
    )


def fetch_gov_schemes(api_url: str | None = None, timeout: float = 5.0) -> list[dict[str, Any]]:
    """Fetch scheme data from the live government schemes API.

    The URL is configurable via ``GOV_SCHEMES_API_URL`` for tests and deployments
    that use a gateway, but defaults to the public gov endpoint.
    """

    url = api_url or os.getenv("GOV_SCHEMES_API_URL") or DEFAULT_GOV_SCHEMES_API_URL
    request = Request(url, headers={"Accept": "application/json", "User-Agent": "scheme-finder/1.0"})
    try:
        with urlopen(request, timeout=timeout) as response:  # noqa: S310 - configured HTTPS API endpoint
            payload = json.loads(response.read().decode("utf-8"))
    except (OSError, URLError, json.JSONDecodeError) as exc:
        raise RuntimeError("Unable to fetch schemes from the government API.") from exc

    return _normalise_scheme_payload(payload)


def find_schemes_for_bio(
    bio: str,
    *,
    api_url: str | None = None,
    schemes: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Return a validated profile and eligibility explanations for a bio."""

    profile = validate_and_parse_bio(bio)
    scheme_data = schemes if schemes is not None else fetch_gov_schemes(api_url)
    results = [explain_eligibility(profile, scheme).as_dict() for scheme in scheme_data]
    return {
        "profile": {
            "income": profile.income,
            "age": profile.age,
            "location": profile.location,
        },
        "results": results,
    }


def explain_eligibility(profile: ApplicantProfile, scheme: dict[str, Any]) -> EligibilityResult:
    """Evaluate one scheme and produce a plain-English explanation."""

    name = str(scheme.get("name") or scheme.get("title") or "Unnamed scheme")
    scheme_id = scheme.get("id") or scheme.get("slug")
    criteria = _extract_criteria(scheme)

    checks: list[tuple[bool, str]] = []

    min_income = _optional_int(criteria.get("min_income"))
    max_income = _optional_int(criteria.get("max_income"))
    if min_income is not None:
        checks.append((profile.income >= min_income, f"income is at least £{min_income:,}"))
    if max_income is not None:
        checks.append((profile.income <= max_income, f"income is no more than £{max_income:,}"))

    min_age = _optional_int(criteria.get("min_age"))
    max_age = _optional_int(criteria.get("max_age"))
    if min_age is not None:
        if profile.age is None:
            checks.append((False, f"age must be supplied and be at least {min_age}"))
        else:
            checks.append((profile.age >= min_age, f"age is at least {min_age}"))
    if max_age is not None:
        if profile.age is None:
            checks.append((False, f"age must be supplied and be no more than {max_age}"))
        else:
            checks.append((profile.age <= max_age, f"age is no more than {max_age}"))

    locations = _normalise_locations(criteria.get("locations") or criteria.get("location"))
    if locations:
        applicant_location = (profile.location or "").lower()
        location_match = any(loc in applicant_location or applicant_location in loc for loc in locations)
        checks.append((location_match, "location matches " + ", ".join(sorted(locations))))

    if not checks:
        return EligibilityResult(
            id=str(scheme_id) if scheme_id is not None else None,
            name=name,
            eligible=True,
            explanation="Eligible: no restrictive eligibility criteria were published for this scheme.",
        )

    eligible = all(passed for passed, _ in checks)
    passed_reasons = [reason for passed, reason in checks if passed]
    failed_reasons = [reason for passed, reason in checks if not passed]

    if eligible:
        explanation = "Eligible because " + "; ".join(passed_reasons) + "."
    else:
        explanation = "Not eligible because " + "; ".join(failed_reasons) + "."
        if passed_reasons:
            explanation += " Criteria met: " + "; ".join(passed_reasons) + "."

    return EligibilityResult(
        id=str(scheme_id) if scheme_id is not None else None,
        name=name,
        eligible=eligible,
        explanation=explanation,
    )


def _extract_income(text: str) -> int | None:
    patterns = [
        r"(?:income|earn(?:ing|s)?|salary|wage)\D{0,20}(\d[\d,]*)",
        r"(?:£|gbp\s*)(\d[\d,]*)",
        r"(\d[\d,]*)\s*(?:pounds|per year|annually|a year)",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            return int(match.group(1).replace(",", ""))
    return None


def _extract_age(text: str) -> int | None:
    patterns = [r"\b(?:age|aged)\s*(\d{1,3})\b", r"\b(\d{1,3})\s*(?:years old|year old|yo)\b"]
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            age = int(match.group(1))
            if 0 <= age <= 125:
                return age
    return None


def _extract_location(text: str) -> str | None:
    match = re.search(r"\b(?:in|from|living in|based in)\s+([A-Za-z][A-Za-z\s-]{1,60})", text, flags=re.IGNORECASE)
    if not match:
        return None
    location = match.group(1).strip(" .,")
    # Stop before common words that often follow the location phrase.
    location = re.split(r"\b(?:and|with|earning|income|salary)\b", location, maxsplit=1, flags=re.IGNORECASE)[0]
    return " ".join(location.split()).lower() or None


def _normalise_scheme_payload(payload: Any) -> list[dict[str, Any]]:
    if isinstance(payload, list):
        return [item for item in payload if isinstance(item, dict)]
    if isinstance(payload, dict):
        for key in ("schemes", "results", "items", "data"):
            value = payload.get(key)
            if isinstance(value, list):
                return [item for item in value if isinstance(item, dict)]
    raise RuntimeError("Government API response did not contain a schemes list.")


def _extract_criteria(scheme: dict[str, Any]) -> dict[str, Any]:
    criteria = scheme.get("eligibility") or scheme.get("criteria") or {}
    if not isinstance(criteria, dict):
        criteria = {}

    # Some APIs put simple criteria at top level; merge them without overriding
    # the explicit nested eligibility object.
    merged = dict(criteria)
    for key in ("min_income", "max_income", "min_age", "max_age", "locations", "location"):
        if key not in merged and key in scheme:
            merged[key] = scheme[key]
    return merged


def _optional_int(value: Any) -> int | None:
    if value is None or value == "":
        return None
    if isinstance(value, bool):
        return None
    try:
        return int(str(value).replace(",", ""))
    except (TypeError, ValueError):
        return None


def _normalise_locations(value: Any) -> set[str]:
    if value is None:
        return set()
    if isinstance(value, str):
        values = [value]
    elif isinstance(value, list | tuple | set):
        values = list(value)
    else:
        return set()
    return {str(item).strip().lower() for item in values if str(item).strip()}
"}

