{"path": "utils/helpers.py", "content": """"Small text helper utilities."""

from __future__ import annotations


ELLIPSIS = "…"


def slugify(text: str) -> str:
    """Convert text to a lowercase, dash-separated slug."""

    return "-".join(text.strip().lower().split())


def truncate(text: str, length: int = 80) -> str:
    """Shorten text to at most ``length`` characters, appending an ellipsis.

    ``length`` must leave room for at least one content character and the
    ellipsis.  Text already within the limit is returned unchanged.
    """

    if length < 2:
        raise ValueError("length must be at least 2")
    if len(text) <= length:
        return text
    return text[: length - len(ELLIPSIS)] + ELLIPSIS
"}

