        captured["timeout"] = timeout
        return FakeResponse()

    monkeypatch.setattr(scheme_finder, "urlopen", fake_urlopen)

    payload = find_schemes_for_bio("I am 45 and earn £12,000 in rural Devon", api_url="https://api.gov.test/schemes")

    assert captured == {"url": "https://api.gov.test/schemes", "timeout": 5.0}
    assert payload["profile"]["income"] == 12000
    assert payload["results"] == [
