        },
        {
            "id": "student",
            "name": "Student Stipend",
            "eligible": False,
            "explanation": "Not eligible because income is at least £20,000.",
        },
    ]


def test_fetch_gov_schemes_wraps_network_errors(monkeypatch):
    def fake_urlopen(request, timeout):
        raise URLError("offline")

    monkeypatch.setattr(scheme_finder, "urlopen", fake_urlopen)

    with pytest.raises(RuntimeError, match="Unable to fetch"):
