    assert response.status_code == 400
    assert response.get_json() == {"error": "Please include your annual income in the bio."}


def test_schemes_route_returns_eligibility_payload(monkeypatch):
    monkeypatch.setattr(
        scheme_finder,
        "urlopen",
        lambda request, timeout: _JsonResponse(
            {"schemes": [{"id": "grant", "name": "Grant", "eligibility": {"max_income": 10000}}]}
        ),
    )
    client = flask_app.test_client()

    response = client.get("/schemes?bio=I%20earn%20%C2%A35,000%20a%20year")

    assert response.status_code == 200
    assert response.get_json()["results"][0]["explanation"] == "Eligible because income is no more than £10,000."


class _JsonResponse:
