            name=name,
            eligible=True,
            explanation="Eligible: no restrictive eligibility criteria were published for this scheme.",
        )

    eligible = all(passed for passed, _ in checks)
    passed_reasons = [reason for passed, reason in checks if passed]
    failed_reasons = [reason for passed, reason in checks if not passed]

    if eligible:
        explanation = "Eligible because " + "; ".join(passed_reasons) + "."
    else:
        explanation = "Not eligible because " + "; ".join(failed_reasons) + "."
        if passed_reasons:
            explanation += " Criteria met: " + "; ".join(passed_reasons) + "."

    return EligibilityResult(
        id=str(scheme_id) if scheme_id is not None else None,
        name=name,
        eligible=eligible,
        explanation=explanation,
    )


def _extract_income(text: str) -> int | None:
    patterns = [
        r"(?:income|earn(?:ing|s)?|salary|wage)\D{0,20}(\d[\d,]*)",
        r"(?:£|gbp\s*)(\d[\d,]*)",
        r"(\d[\d,]*)\s*(?:pounds|per year|annually|a year)",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            return int(match.group(1).replace(",", ""))
    return None


def _extract_age(text: str) -> int | None:
    patterns = [r"\b(?:age|aged)\s*(\d{1,3})\b", r"\b(\d{1,3})\s*(?:years old|year old|yo)\b"]
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            age = int(match.group(1))
            if 0 <= age <= 125:
                return age
    return None


def _extract_location(text: str) -> str | None:
    match = re.search(r"\b(?:in|from|living in|based in)\s+([A-Za-z][A-Za-z\s-]{1,60})", text, flags=re.IGNORECASE)
    if not match:
        return None
    location = match.group(1).strip(" .,")
    # Stop before common words that often follow the location phrase.
    location = re.split(r"\b(?:and|with|earning|income|salary)\b", location, maxsplit=1, flags=re.IGNORECASE)[0]
    return " ".join(location.split()).lower() or None


def _normalise_scheme_payload(payload: Any) -> list[dict[str, Any]]:
    if isinstance(payload, list):
        return [item for item in payload if isinstance(item, dict)]
    if isinstance(payload, dict):
        for key in ("schemes", "results", "items", "data"):
            value = payload.get(key)
            if isinstance(value, list):
                return [item for item in value if isinstance(item, dict)]
    raise RuntimeError("Government API response did not contain a schemes list.")


def _extract_criteria(scheme: dict[str, Any]) -> dict[str, Any]:
    criteria = scheme.get("eligibility") or scheme.get("criteria") or {}
    if not isinstance(criteria, dict):
        criteria = {}

    # Some APIs put simple criteria at top level; merge them without overriding
    # the explicit nested eligibility object.
    merged = dict(criteria)
    for key in ("min_income", "max_income", "min_age", "max_age", "locations", "location"):
        if key not in merged and key in scheme:
            merged[key] = scheme[key]
    return merged


def _optional_int(value: Any) -> int | None:
    if value is None or value == "":
        return None
    if isinstance(value, bool):
        return None
    try:
        return int(str(value).replace(",", ""))
    except (TypeError, ValueError):
        return None


def _normalise_locations(value: Any) -> set[str]:
    if value is None:
        return set()
    if isinstance(value, str):
        values = [value]
    elif isinstance(value, list | tuple | set):
        values = list(value)
    else:
        return set()
    return {str(item).strip().lower() for item in values if str(item).strip()}

