def test_explain_eligibility_includes_reasons_for_match():
    profile = ApplicantProfile(
        bio="I am 67 in rural Devon earning £12,000",
        income=12000,
        age=67,
        location="rural devon",
    )
    result = explain_eligibility(
        profile,
        {
            "id": "pension-top-up",
            "name": "Senior Pension Top-up",
            "eligibility": {"max_income": 15000, "min_age": 65, "locations": ["Devon"]},
        },
    )

    assert result.eligible is True
    assert result.name == "Senior Pension Top-up"
    assert "Eligible because" in result.explanation
    assert "income is no more than £15,000" in result.explanation
    assert "age is at least 65" in result.explanation
    assert "location matches" in result.explanation


def test_explain_eligibility_includes_reasons_for_rejection():
    profile = ApplicantProfile(bio="Student earning £25,000", income=25000, age=20)
    result = explain_eligibility(
        profile,
        {"name": "Student Stipend", "eligibility": {"max_income": 20000, "max_age": 25}},
    )

    assert result.eligible is False
    assert result.explanation.startswith("Not eligible because")
    assert "income is no more than £20,000" in result.explanation
    assert "Criteria met: age is no more than 25" in result.explanation


